CREATE TABLE persoana (
  cheie        TEXT PRIMARY KEY,   -- "ema" / "adi"
  pozitie      INTEGER NOT NULL,
  nume         TEXT NOT NULL,      -- "Ema"
  pronume      TEXT NOT NULL,      -- "ea" / "el"
  portie       TEXT NOT NULL CHECK (portie IN ('S','M')),
  portie_nume  TEXT NOT NULL,      -- "standard" / "mare"
  kcal         INTEGER NOT NULL,
  proteine     INTEGER NOT NULL,
  grasimi      INTEGER NOT NULL,
  carbo        INTEGER NOT NULL,
  fibre_tinta  TEXT NOT NULL,      -- "25–30"
  apa          TEXT NOT NULL       -- litri pe zi: "2,5"
);
INSERT INTO "persoana" VALUES('ema',1,'Ema','ea','S','standard',2200,150,65,255,'25–30','2,5');
INSERT INTO "persoana" VALUES('adi',2,'Adi','el','M','mare',2400,180,75,250,'30–38','3');
CREATE TABLE reteta (
  id          TEXT PRIMARY KEY,   -- "MD1", "P12"
  pozitie     INTEGER NOT NULL,   -- ordinea în liste
  grup        TEXT NOT NULL,      -- "Mic dejun" / "Gustări" / "Feluri principale"
  nume        TEXT NOT NULL,      -- numele întreg, cum apare în meniu
  scurt       TEXT NOT NULL,      -- numele scurt, pentru calendar și cardurile de pe site
  masa        TEXT NOT NULL,      -- "prânz/cină", "mic dejun 🥚", "gustare 🏋️"
  timp        TEXT NOT NULL,      -- "45′ (10 activ)"
  tine        TEXT NOT NULL,      -- cât ține la frigider: "3 zile", "nu", "—"
  cum         TEXT NOT NULL,      -- rezumatul: cum se face, în două-trei fraze
  -- modul de preparare, pas cu pas: un pas pe linie, fără numerotare (numerele se pun
  -- la afișare). Aici stau tehnica și ordinea — temperaturi, timpi, ce intră când și de ce.
  preparare   TEXT NOT NULL DEFAULT '',
  sfat        TEXT NOT NULL DEFAULT '',   -- „de ce așa" — nota de bucătar / nutriționist
  varianta    TEXT NOT NULL DEFAULT '',  -- „merge și cu…"

  -- pentru calendarul de gătit
  proaspat    INTEGER NOT NULL DEFAULT 0 CHECK (proaspat IN (0,1)),  -- se face ×2, în ziua aia (peștele)
  congelator  INTEGER NOT NULL DEFAULT 0 CHECK (congelator IN (0,1)),-- se face ×8, jumătate la congelator
  semn        TEXT NOT NULL DEFAULT '',   -- 🐟 lângă numele din calendar
  carne_rosie TEXT,               -- "vită" / "porc" — pentru verificarea „max 2 feluri/săpt."
  peste       TEXT,               -- "doradă" / "păstrăv" — pentru verificarea „pește 2×/săpt."
  nota_gatit  TEXT                -- se lipește în coloana „ce se gătește seara"
);
INSERT INTO "reteta" VALUES('MD1',1,'Mic dejun','Omletă cu legume și brânză de vaci, pâine integrală + banană','Omletă cu legume','mic dejun 🥚','15′','nu','Ciupercile și ceapa verde 3 min în ulei, spanacul și roșiile 1 min, ouăle bătute deasupra, amestecat până se leagă. Brânza de vaci alături. Banana la final.','Taie ciupercile felii subțiri, roșiile cuburi, ceapa verde inele; spală spanacul. Bate ouăle cu furculița, cu sare și piper, până sunt omogene (nu spumă).
Încinge tigaia la foc mediu cu uleiul de măsline și călește ciupercile și ceapa verde 3 min, întinse, nu îngrămădite — ciupercile trebuie să lase apa și să prindă culoare.
Adaugă roșiile și spanacul, 1 min, cât să cadă spanacul. Dacă legumele au lăsat zeamă, las-o să scadă — altfel omleta iese apoasă.
Dă focul mic, toarnă ouăle peste legume și amestecă lent cu spatula, trăgând marginile spre centru, 2–3 min, până se leagă dar rămâne cremoasă la mijloc.
Oprește focul cu 30 de secunde mai devreme: omleta se termină singură în tigaia fierbinte.
Prăjește pâinea uscat (fără unt). Brânza de vaci alături, cu mărar sau boia, sare și piper. Banana la final.','Ouăle la foc mic rămân moi; la foc mare proteina se strânge, elimină apa și omleta devine cauciucată. Vitamina C din roșii și ardei ajută absorbția fierului din gălbenuș. Brânza stă alături, nu în omletă — lactatele merg cu ouă, dar niciodată cu carne sau pește (regula casei).','Legumele = ce e în casă (ardei, dovlecel, praz). Banana ↔ măr / 150 g fructe de pădure.',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('MD2',2,'Mic dejun','Ovăz peste noapte cu skyr, fructe de pădure, chia și nuci','Ovăz peste noapte','mic dejun','5′ (seara)','3 zile','Totul într-un borcan, amestecat, la frigider peste noapte. Nucile deasupra dimineața. Scorțișoară.','Seara, într-un borcan de 500 ml: fulgii de ovăz, chia, skyr-ul și laptele. Amestecă bine, până nu mai rămâne ovăz uscat pe fund.
Adaugă fructele de pădure (merg direct congelate — se dezgheață peste noapte) și un vârf de scorțișoară. Amestecă scurt.
Închide borcanul și ține-l la frigider minimum 6 ore. Chia se umflă și leagă compoziția ca un budincă.
Dimineața presară nucile tocate grosier, chiar înainte de a mânca. Dacă e prea gros, subțiază cu 1–2 linguri de lapte.','Nucile se pun la final ca să rămână crocante și ca grăsimile lor să nu se oxideze peste noapte. Ovăzul ținut la rece formează amidon rezistent — hrană pentru bacteriile din colon și o creștere mai lină a glicemiei decât la ovăzul fiert. Se face pentru 2–3 zile deodată.','Iarna: ovăz fiert în lapte, skyr adăugat la final.',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('MD3',3,'Mic dejun','Bol de iaurt grec cu banană, unt de arahide, ovăz și in','Bol de iaurt grec','mic dejun','5′','nu','Iaurtul în bol, banana felii și afinele, ovăzul și inul deasupra, untul de arahide picurat. Scorțișoară.','Pune iaurtul grec în bol și întinde-l ușor cu dosul lingurii.
Taie banana felii și așaz-o cu afinele pe jumătate din suprafață.
Presară fulgii de ovăz și inul măcinat pe cealaltă jumătate. Inul trebuie măcinat — sămânța întreagă trece nedigerată.
Picură untul de arahide deasupra; dacă e prea tare, amestecă-l întâi cu o lingură de apă caldă, ca să curgă. Pudrează cu scorțișoară.','Inul măcinat pe loc (10 secunde în râșnița de cafea) își păstrează omega-3; măcinat din comerț se oxidează în câteva săptămâni. Untul de arahide: doar cel cu 100% arahide, fără zahăr și fără ulei de palmier. Banana mai coaptă înseamnă mai dulce, fără să adaugi nimic.','',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('MD4',4,'Mic dejun','Ouă ochiuri cu avocado pe pâine, roșii, castravete, brânză de vaci + măr','Ochiuri cu avocado','mic dejun 🥚','10′','nu','Avocado zdrobit cu lămâie pe pâine, ouăle (ochiuri sau fierte moi) deasupra, rucola, roșiile, castravetele și brânza alături.','Prăjește feliile de pâine uscat, în tigaie sau prăjitor, până sunt crocante — așa suportă avocado fără să se înmoaie.
Zdrobește avocado cu furculița, cu suc de lămâie, sare și piper. Lămâia nu e doar pentru gust: ține avocado verde.
Ouăle: fie ochiuri în apă (apă la fiert mic, o lingură de oțet, oul spart întâi într-o cană și lăsat ușor în apă, 3 min), fie în tigaie la foc mic, cu capac, ca să nu se ardă marginile.
Întinde avocado pe pâine, așază ouăle deasupra, sare și piper.
Alături: rucola, roșiile felii, castravetele și brânza de vaci cu mărar. Un strop de lămâie peste salată.','Gălbenușul lăsat moale păstrează mai bine colina și vitaminele A, D și E, care se degradează la gătire lungă. Grăsimea din avocado ajută la absorbția vitaminelor liposolubile din gălbenuș și a carotenoizilor din roșii și rucola.','',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('G1',5,'Gustări','Skyr cu măr și migdale','Skyr cu măr','gustare','2′','—','Se mănâncă împreună sau separat. Scorțișoară pe măr.','Pune skyr-ul în bol.
Taie mărul cubulețe, cu coajă cu tot — acolo sunt fibrele și polifenolii. Presară scorțișoară peste el.
Adaugă migdalele, întregi sau tocate grosier, alături sau deasupra.','Proteina din skyr plus fibra din măr țin de foame ~3 ore — exact ce trebuie la 16:00, ca să nu ajungi flămând la cină. Migdalele întregi se mestecă mai mult și se digeră mai lent decât cele măcinate; ~15 g ajung, sunt dense caloric.','',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('G2',6,'Gustări','Brânză de vaci cu pâine integrală și legume crude','Brânză de vaci cu pâine','gustare','5′','—','Brânza pe pâine cu sare, piper, mărar sau boia; legumele crude, bețe, alături.','Amestecă brânza de vaci cu sare, piper și mărar tocat (sau boia afumată, dacă vrei alt gust).
Întinde-o pe feliile de pâine integrală.
Taie castravetele, ardeiul și morcovul bețe și pune-le alături — se mănâncă crude, cu mâna.','Brânza de vaci e în cea mai mare parte cazeină, proteină cu digestie lentă: gustarea ține până la cină. Legumele tăiate bețe se mănâncă în cantitate mai mare decât aceleași legume tocate în salată — e o diferență reală de câteva sute de grame pe săptămână.','Ridichi lângă castravete — doar la cine le vrea.',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('G3',7,'Gustări','Shake post-sală: lapte, skyr, banană, unt de arahide','Shake post-sală','gustare 🏋️','3′','—','Totul la blender; cacao sau scorțișoară opțional. Fără blender: skyr + banană tăiată + laptele băut alături.','Pune în blender laptele, skyr-ul, banana și untul de arahide.
Blender 30–40 de secunde, până e omogen. Cacao neîndulcită sau scorțișoară, opțional.
Bea-l în prima oră după antrenament.
Fără blender: skyr-ul cu banana tăiată mărunt și zdrobită cu furculița, iar laptele băut alături.','După antrenamentul de forță contează combinația proteină + carbohidrați: skyr-ul și laptele dau ~30 g proteine bogate în leucină, banana reface glicogenul. Untul de arahide rămâne la 10–15 g — grăsimea încetinește golirea stomacului, adică exact opusul a ce vrei acum.','De ce: proteină rapidă + carbohidrați simpli după forță.',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('P1',8,'Feluri principale','Pui la cuptor cu legume la tavă, cartof dulce și sos de tahini cu lămâie','Pui la cuptor cu legume la tavă','prânz/cină','45′ (10 activ)','3 zile','Cartoful dulce cuburi + morcovul cu ½ din ulei și boia afumată, 20 min la 200 °C. Se adaugă puiul (oregano, usturoi, lămâie), broccoli, ceapa și ardeiul cu restul de ulei, încă 20–25 min. Sos: tahini + lămâie + usturoi pisat + 2 linguri apă + sare, amestecat până e cremos.','Încinge cuptorul la 200 °C. Taie cartoful dulce cuburi de 2 cm și morcovul rondele groase; amestecă-le într-un bol cu jumătate din ulei, boia afumată, sare și piper.
Întinde-le pe tavă cu hârtie de copt, într-un singur strat, fără să se atingă — înghesuite se aburesc în loc să se rumenească. 20 min.
Între timp condimentează pieptul de pui cu oregano, usturoi pisat, coajă și suc de lămâie, sare și piper. Taie broccoli buchețele, ceapa felii groase, ardeiul fâșii și amestecă-le cu restul de ulei.
Scoate tava, împinge cartofii într-o parte, adaugă puiul și legumele verzi. Încă 20–25 min, până puiul ajunge la 74 °C la mijloc (sau până zeama iese limpede).
Sosul: amestecă tahini cu sucul de lămâie și usturoiul pisat — se va strânge și se va face pastă. Adaugă 2 linguri de apă rece, lingură cu lingură, bătând cu furculița, până devine cremos ca o smântână. Sare.
Lasă puiul 5 min înainte să-l tai. Sosul se toarnă în farfurie, nu la cuptor.','Broccoli intră în a doua parte a coacerii ca să nu-și piardă culoarea și sulforafanul. Puiul scos la 74 °C rămâne suculent — peste, se usucă și devine făinos. Sosul de tahini ține locul celui de iaurt la masa cu carne (regula casei) și aduce calciu, magneziu și seleniu.','',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('P2',9,'Feluri principale','Tocăniță de vită cu ciuperci, mămăligă și salată de varză roșie cu mere','Tocăniță de vită cu mămăligă','prânz/cină','75′ (15 activ)','4 zile · congelator','Vita rumenită în ½ ulei, ceapa + morcovul 5 min, ciupercile + ardeiul, roșiile pasate + apă cât să acopere, boia, cimbru, dafin. La foc mic 60 min (25 la oala sub presiune). Mămăliga proaspăt, 10 min. Salata: varză roșie tăiată fin frecată cu sare + oțet, mere julienne, restul de ulei.','Taie vita cuburi de 3 cm și usuc-o cu un șervet: carnea udă nu se rumenește, fierbe. Sare și piper.
Încinge bine oala cu jumătate din ulei și rumenește carnea în două tranșe, 2–3 min pe parte, fără s-o înghesui. Scoate-o deoparte.
În aceeași oală: ceapa și morcovul 5 min, apoi ciupercile și ardeiul, până ciupercile lasă apa și se rumenesc. Dezlipește cu lingura de lemn tot ce s-a prins pe fund — acolo e gustul.
Pune carnea înapoi cu roșiile pasate, boiaua, cimbrul, foaia de dafin și apă cât să acopere. Foc mic, cu capac, 60 min (25 min la oala sub presiune), până carnea se desface cu furculița.
Mămăliga se face proaspăt, la final: apă cu sare la fiert, mălaiul în ploaie, amestecat continuu, 10 min la foc mic.
Salata: varza roșie tăiată foarte fin și frecată cu sare și oțet 2 min (se înmoaie și își aprinde culoarea), mărul julienne, restul de ulei.','Fără telemea sau smântână peste mămăligă — e masă cu carne (regula casei). Fierberea lungă la foc mic transformă colagenul din vită în gelatină: de acolo vine textura, nu din grăsime. Varza roșie crudă cu măr adaugă fibre, vitamina C și antociani lângă un fel gătit mult.','Fără telemea peste mămăligă — regula: nu amestecăm lactate cu carne.',0,0,'','vită',NULL,'(60 min la foc mic — se pune la fiert și se face altceva)');
INSERT INTO "reteta" VALUES('P3',10,'Feluri principale','Doradă la cuptor cu fasole verde cu usturoi, salată de rucola, quinoa și sos de lămâie cu mărar 🐟','Doradă cu quinoa','cină','25′','1 zi (rece)','Dorada (întreagă, curățată, sau file) cu lămâie + usturoi + ½ din ulei, 18–20 min la 200 °C. Quinoa fiartă 15 min (1:2 apă). Fasolea verde 5 min în apă clocotită, apoi 1 min în tigaie cu usturoi și ulei. Rucola cu roșii cherry și un strop de lămâie. Sos: lămâie + ½ din ulei + mărar tocat + usturoi.','Cuptorul la 200 °C. Clătește quinoa în sită sub apă rece 30 de secunde (scapi de saponine, gustul amărui), apoi fierbe-o 15 min în dublu volum de apă cu sare, cu capac. La final las-o 5 min deoparte și afâneaz-o cu furculița.
Usucă dorada cu un șervet, crestează pielea de 2–3 ori, sare și piper pe dinăuntru și pe dinafară, felii de lămâie și usturoi în burtă, jumătate din ulei deasupra.
Coace 18–20 min la 200 °C (file: 12–14 min). E gata când carnea e opacă și se desprinde de os.
Fasolea verde: 5 min în apă clocotită cu sare, scursă, apoi 1 min în tigaie cu usturoi feliat și un strop de ulei.
Salata: rucola cu roșiile tăiate în două și un strop de lămâie.
Sosul: suc de lămâie, restul de ulei, mărar tocat și usturoi pisat, bătute cu furculița; se toarnă peste pește la servire.','Peștele se coace, nu se prăjește: omega-3 se degradează la temperaturi mari și timp lung. Se gătește proaspăt, în ziua aceea — peștele reîncălzit își pierde textura și capătă miros. Lângă pește nu punem lactate (regula casei), de aceea sosul e pe bază de lămâie și ulei.','Se face ×2, proaspăt. Cântărită ca file (la pește întreg, ~½ din greutate e carne). Merge la fel cu chefal, păstrăv sau — mai rar — somon (+150 kcal).',1,0,'🐟',NULL,'doradă','+ salata de ton asamblată pt. mâine');
INSERT INTO "reteta" VALUES('P4',11,'Feluri principale','Salată de ton cu năut, legume crude și vinegretă de muștar 🐟','Salată de ton','prânz','10′ (fără gătit)','2 zile','Totul amestecat; tonul scurs, rupt cu furculița deasupra, măslinele felii. Dressing: muștar + lămâie + ulei + mărar, bătute cu furculița. Pâinea alături.','Scurge bine tonul (apasă capacul conservei) și năutul; clătește năutul sub apă rece, ca să scapi de lichidul de conservare.
Taie castravetele, ardeiul și roșiile cuburi, ceapa foarte fin — dacă e iute, ține-o 5 min în apă rece cu oțet. Salata verde se rupe cu mâna, nu se taie.
Vinegreta: muștar, suc de lămâie, ulei de măsline și mărar, bătute cu furculița până se leagă. Sare, piper.
Amestecă legumele cu năutul și dressingul, apoi pune tonul deasupra, rupt cu furculița — nu amestecat, ca să rămână bucăți. Măslinele felii.
Pâinea integrală alături. Dacă o pregătești pentru a doua zi, ține dressingul separat și pune-l la masă.','Năutul aduce fibrele și amidonul care lipsesc din ton: împreună ies o masă completă, fără gătit. Tonul e pește slab — omega-3 vine de la doradă și păstrăv, la cinele de marți. Se ține 2 zile la frigider, dar salata verde se adaugă la servire.','Ridichi — doar la cine le vrea. Săpt. 2: 60 g linte uscată fiartă în loc de năut. Tonul e pește slab — omega-3 vine de la doradă / păstrăv / chefal, la cinele de marți.',0,0,'🐟',NULL,'ton',NULL);
INSERT INTO "reteta" VALUES('P5',12,'Feluri principale','Chili de linte cu pui tocat, avocado și salată de castraveți','Chili de linte cu pui','prânz/cină','45′ (10 activ)','4 zile · congelator','Carnea rumenită în ulei, ceapa + ardeiul + morcovul 5 min, lintea + roșiile + apă (2 degete peste), chimion, boia afumată, usturoi, oregano, chili. La foc mic 30–35 min. Alături: castravete felii cu lămâie, mărar și sare. Avocado cuburi peste chili la servire.','Încinge oala cu uleiul și rumenește puiul tocat, desfăcându-l cu lingura, până nu mai e roz și prinde puțină culoare.
Adaugă ceapa, ardeiul și morcovul tocate mărunt; 5 min, până se înmoaie.
Pune chimionul, boiaua afumată, oregano, usturoiul și chili și prăjește-le 30–60 de secunde în grăsime — așa își eliberează aromele; puse direct în apă rămân fade.
Adaugă lintea clătită, roșiile pasate și apă cu două degete peste. Foc mic, capac întredeschis, 30–35 min, până lintea e moale dar întreagă.
Sarea se pune la final: pusă devreme, întărește coaja lintei.
Salata: castravete felii cu suc de lămâie, mărar și sare. Avocado cuburi se pune peste chili în farfurie, la servire — nu se fierbe și nu se congelează.','Se face ×8 și jumătate merge la congelator: chili-ul se congelează perfect și e mai bun a doua zi. Lintea cu puiul dau ~10 g de fibre pe porție și o proteină completă. Avocado adaugă grăsimi bune și taie din picant — de aceea intră crud, la sfârșit.','Se face ×8 — jumătate la congelator. Piept de pui tocat acasă sau la măcelar; pui tocat comercial: +35 kcal, −8 g P.',0,1,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('P6',13,'Feluri principale','Paste integrale cu pui, sos de roșii cu dovlecel și salată de rucola cu roșii cherry','Paste cu pui și dovlecel','prânz/cină','30′','3 zile','Puiul fâșii rumenit, scos. Ceapa + dovlecelul 5 min, roșiile pasate, busuioc, oregano, usturoi, 10 min. Puiul înapoi. Pastele al dente, amestecate în sos; măsline felii deasupra. Rucola + roșii cherry cu lămâie alături.','Pune apa pentru paste la fiert, sărată ca marea.
Taie puiul fâșii, condimentează-l și rumenește-l 3–4 min în tigaie încinsă cu jumătate din ulei, în strat subțire. Scoate-l — ținut tot timpul în sos, se usucă.
În aceeași tigaie: ceapa și dovlecelul cuburi, 5 min. Adaugă roșiile pasate, usturoiul, busuiocul și oregano și fierbe 10 min la foc mic, până sosul se leagă.
Fierbe pastele al dente — un minut mai puțin decât scrie pe pachet — și păstrează o cană din apa lor.
Pune puiul înapoi în sos, adaugă pastele scurse și 2–3 linguri din apa de la paste; amestecă 1 min pe foc, cât amidonul leagă sosul de paste. Măslinele felii deasupra.
Alături: rucola cu roșii cherry, un strop de lămâie și restul de ulei.','Pastele al dente au indice glicemic mai mic decât cele răsfierte; integrale, au de 3–4 ori mai multe fibre decât cele albe. Fără parmezan — e masă cu carne (regula casei); gustul îl dau busuiocul, usturoiul și măslinele.','',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('P7',14,'Feluri principale','Cotlet de porc cu piure de conopidă și morcov, cartofi copți și salată de varză','Cotlet de porc cu piure de conopidă','prânz/cină','40′','3 zile (salata proaspăt)','Conopida + morcovul fierte 15 min, pasate cu ½ din ulei + puțină apă de la fiert + usturoi + nucșoară → piure cremos. Cartofii felii cu rozmarin la cuptor, 25 min la 200 °C. Cotletul bătut subțire, condimentat, 3–4 min pe parte în tigaie încinsă; muștar deasupra. Salata: varză frecată cu sare, oțet, chimen, ulei.','Cuptorul la 200 °C. Cartofii feliați de 1 cm, amestecați cu jumătate din ulei, rozmarin și sare, pe tavă într-un singur strat, 25 min, întorși o dată la mijloc.
Fierbe conopida și morcovul 15 min în apă cu puțină sare, până se străpung ușor cu furculița. Scurge-le, dar păstrează puțină apă de la fiert.
Pasează-le cu restul de ulei, usturoi, un vârf de nucșoară, sare și 2–3 linguri din apa de la fiert, până iese un piure cremos. Fără lapte sau unt — e masă cu carne.
Bate cotletul până are grosime uniformă de ~1,5 cm și condimentează-l cu sare, piper și cimbru.
Tigaia foarte bine încinsă: 3–4 min pe fiecare parte, fără să miști carnea în primul minut, ca să se formeze crusta. Apoi las-o 5 min pe un fund de lemn, înainte de tăiere.
Salata: varza tăiată fin, frecată cu sare 1 min, apoi oțet, chimen și puțin ulei. Muștarul se pune peste cotlet, la servire.','Piureul de conopidă cu morcov are cam o treime din caloriile unuia de cartofi și de câteva ori mai multe fibre — de aceea cartofii rămân puțini și copți, nu pasați. Carnea odihnită 5 min își ține zeama înăuntru; tăiată imediat, o lasă pe tocător.','Piureul merge și cu broccoli în loc de morcov.',0,0,'','porc',NULL,NULL);
INSERT INTO "reteta" VALUES('P8',15,'Feluri principale','Curry de pui cu conopidă, spanac și năut, orez basmati','Curry de pui cu năut','prânz/cină','35′','3 zile','Ceapa + ghimbir + usturoi în ulei, curry + turmeric + chimion 1 min, puiul 5 min, roșiile + laptele de cocos + conopida + năutul, 15 min. Spanacul la final, 2 min. Orezul fiert separat. Coriandru deasupra.','Pune orezul basmati la fiert: 1 parte orez la 1,5 apă, capac, 12 min, apoi încă 5 min deoparte, fără să ridici capacul.
Călește ceapa tocată în ulei 3–4 min, apoi adaugă ghimbirul ras și usturoiul, 30 de secunde.
Pune curry-ul, turmericul și chimionul și prăjește-le 1 min, până miros. Turmericul are nevoie de grăsime și de un praf de piper negru ca să fie absorbit.
Adaugă puiul cubulețe, 5 min, doar cât se albește pe toate părțile.
Toarnă roșiile, laptele de cocos și pune conopida buchețele și năutul scurs; fierbe 15 min la foc mic, fără capac, până conopida e moale și sosul se leagă.
Spanacul la final, 2 min, doar cât cade. Coriandru proaspăt și un strop de lămâie deasupra.','Laptele de cocos light dă cremozitate cu o treime din grăsimile celui gras — de aceea sunt suficiente 50–60 g. Conopida și spanacul țin legumele la 40% din farfurie fără să crească caloriile, iar năutul completează orezul cu fibre și proteină vegetală.','',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('P10',16,'Feluri principale','Chiftele de pui la cuptor cu salată grecească, orez brun și sos de tahini','Chiftele de pui cu orez brun','prânz/cină','45′','3 zile (salata proaspăt)','Pieptul tocat (acasă sau la măcelar) cu ovăz, ceapă rasă, usturoi, pătrunjel → chiftele, 20–25 min la 200 °C. Orezul brun 30 min. Salata: roșii, castravete, ceapă roșie, ardei, măsline, oregano, ulei. Sos: tahini + lămâie + usturoi + apă.','Pune orezul brun la fiert — 30 min, are nevoie de cel mai mult timp din toată rețeta.
Cuptorul la 200 °C. Amestecă pieptul tocat cu fulgii de ovăz, ceapa rasă și stoarsă de zeamă, usturoiul, pătrunjelul tocat, sare și piper.
Lasă compoziția 10 min: ovăzul absoarbe apa și chiftelele nu se mai sfărâmă.
Formează bile de ~40 g cu mâinile ude și așază-le pe tavă cu hârtie de copt. 20–25 min, până sunt aurii. La cuptor, nu în tigaie — nu mai intră ulei în plus.
Salata: roșii, castravete și ardei cuburi, ceapă roșie felii subțiri, oregano și ulei de măsline. Măslinele se pun în farfurie, nu în salata comună.
Sosul: tahini cu lămâie și usturoi, subțiat cu apă rece lingură cu lingură, bătut până e cremos.','Ovăzul ține locul pesmetului și aduce fibre solubile în loc de amidon rafinat. Chiftelele din piept de pui, coapte, au aproximativ o treime din grăsimea celor din carne tocată grasă, prăjite. Salata grecească e fără brânză: masă cu carne.','Măslinele se pun în farfurie, nu în salata comună.',0,0,'',NULL,NULL,NULL);
INSERT INTO "reteta" VALUES('P11',17,'Feluri principale','Mușchi de porc la grătar cu piure de broccoli și dovlecel, hrișcă și sos de roșii cu busuioc','Mușchi de porc cu piure de broccoli','prânz/cină','30′','3 zile','Broccoli + dovlecelul fierte 8 min la abur, pasate cu ½ din ulei, usturoi, lămâie, sare → piure verde. Hrișca fiartă 15 min. Mușchiul de porc medalioane de 2 cm, condimentat (boia, cimbru, usturoi), 3–4 min pe parte pe grătar/tigaie încinsă. Sos: roșii pasate încălzite cu ceapă și busuioc, 5 min. Semințe de dovleac peste piure.','Pune hrișca la fiert: 1 parte la 2 de apă, 15 min cu capac, apoi 5 min deoparte. Dacă o prăjești uscat un minut înainte de a turna apa, capătă gust de alună.
Fierbe broccoli și dovlecelul la abur 8 min — la abur, nu în apă, ca vitaminele să nu rămână în oală. Trebuie să iasă verzi, nu măslinii.
Pasează-le cu jumătate din ulei, usturoi, un strop de lămâie și sare, până iese un piure verde, gros. Dacă e prea tare, o lingură din apa de la abur.
Taie mușchiul medalioane de 2 cm și condimentează-l cu boia, cimbru, usturoi, sare și piper.
Tigaia-grătar foarte încinsă: 3–4 min pe parte, fără să le miști. Apoi 5 min de odihnă.
Sosul: roșiile pasate încălzite cu ceapa tocată mărunt și busuioc, 5 min, până se îngroașă. Semințele de dovleac, prăjite uscat 1 min, se presară peste piure la final.','Mușchiul de porc e una dintre cele mai slabe bucăți de carne roșie (sub 3 g grăsime la 100 g): se gătește repede, la foc mare, altfel se usucă. Piureul verde e legume, nu amidon — hrișca e cea care ține cei 20% din farfurie, iar ea aduce și magneziu și rutin.','Merge și cu cotlet de porc sau piept de pui. Piureul merge și din conopidă + mazăre.',0,0,'','porc',NULL,NULL);
INSERT INTO "reteta" VALUES('P12',18,'Feluri principale','Stir-fry de vită cu broccoli, ardei, ciuperci și varză, orez basmati, sos soia-ghimbir, caju','Stir-fry de vită','prânz/cină','25′','2 zile','Tigaie foarte încinsă; vita fâșii 2 min, scoasă. Broccoli + ardeiul întâi, apoi ciupercile + varza, 5–6 min. Vita înapoi, soia + usturoi + ghimbir, 1 min. Ceapă verde și caju deasupra.','Fierbe orezul basmati: 1 la 1,5 apă, capac, 12 min, plus 5 min deoparte.
Pregătește tot înainte să aprinzi focul: vita fâșii subțiri tăiate contra fibrei, legumele tăiate, sosul de soia amestecat cu usturoiul și ghimbirul ras. Un stir-fry durează 8 minute — n-ai când să tai pe parcurs.
Tigaia (sau wokul) foarte încinsă, un strop de ulei: vita, în strat subțire, 2 min, întoarsă o singură dată. Scoate-o.
Restul de ulei: broccoli și ardeiul 3 min, apoi ciupercile și varza încă 2–3 min. Legumele trebuie să rămână crocante.
Pune vita înapoi, toarnă sosul de soia cu usturoi și ghimbir și ține totul pe foc încă 1 min, cât se glazurează.
Ceapa verde și caju, prăjit uscat, deasupra, la final.','Focul mare și timpul scurt păstrează legumele crocante și vitaminele hidrosolubile (C, din grupul B), care se pierd la fierbere lungă. Sosul de soia e sărat — cele 15 g aduc aproape un gram de sare, deci nu mai punem sare deloc în mâncare.','',0,0,'','vită',NULL,NULL);
INSERT INTO "reteta" VALUES('P13',19,'Feluri principale','Păstrăv la cuptor cu legume ratatouille, cartofi și sos de lămâie cu usturoi 🐟','Păstrăv cu ratatouille','cină','35′','1 zi (rece)','Cartofii felii cu ½ ulei + rozmarin, 20 min la 200 °C. Legumele cuburi cu restul de ulei + cimbru, în aceeași tavă, + păstrăvul cu lămâie și usturoi deasupra, încă 15–18 min. Sos: lămâie + ulei + usturoi + mărar (se toarnă peste pește la servire).','Cuptorul la 200 °C. Cartofii feliați de 1 cm, cu jumătate din ulei, rozmarin și sare, pe tavă, 20 min.
Taie vinetele, dovlecelul, ardeiul, ceapa și roșiile cuburi de 2 cm și amestecă-le cu restul de ulei, cimbru, sare și piper.
Scoate tava, împinge cartofii într-o parte și adaugă legumele.
Usucă păstrăvul, crestează-l, pune sare, piper, felii de lămâie și usturoi în burtă și așaz-l peste legume.
Încă 15–18 min, până carnea peștelui e opacă și se desprinde ușor de os. Păstrăvul se face repede — mai mult îl usucă.
Sosul: lămâie, ulei, usturoi pisat și mărar, bătute cu furculița și turnate peste pește în farfurie.','Peștele și legumele în aceeași tavă lucrează împreună: zeama legumelor ține peștele umed, iar grăsimea lui aromatizează legumele. Păstrăvul e, alături de doradă, sursa de omega-3 a săptămânii — de aceea se gătește proaspăt și blând, la cuptor, nu prăjit.','Se face ×2, proaspăt. Merge la fel cu chefal sau doradă. Ridichi — doar la cine le vrea.',1,0,'🐟',NULL,'păstrăv','+ salata de ton asamblată pt. mâine');
CREATE TABLE reteta_element (
  id        INTEGER PRIMARY KEY,
  reteta_id TEXT NOT NULL REFERENCES reteta(id) ON DELETE CASCADE,
  pozitie   INTEGER NOT NULL,
  eticheta  TEXT NOT NULL,        -- se păstrează exact, spațiile incluse (o rețetă are două elemente „Amidon")
  UNIQUE (reteta_id, pozitie)
);
